// @name Clock
// @background #0b1020
// @refresh 1
// An analog clock drawn as a JSX <svg>: no markup is built or parsed.
// `at` (a field) pins the time, for a snapshot; empty, it is the clock.
const C = 240
const at = (angle, r) => [C + r * Math.sin(angle), C - r * Math.cos(angle)]
const Hand = ({ angle, from, to, width, color }) => {
  const [x1, y1] = at(angle, from)
  const [x2, y2] = at(angle, to)
  return <line x1={x1} y1={y1} x2={x2} y2={y2} stroke={color} strokeWidth={width} strokeLinecap="round" />
}
// On a round panel the dial's marks reach to 14 units inside the rim.
const ROUND_SCALE = (C - 14) / 204
const days = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT']

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it; solid inks on color e-paper,
// where the navy dial and its thin grey ticks dither to faint dots.
const themeOf = (app) => {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return THEMES.high
  if (mode === 'auto' && app.frame.paper === true) return THEMES.inks
  return THEMES.color
}

const THEMES = {
  color: {
    page: '#0b1020', face: '#131c38', rim: '#2a3a6b', tick: '#e2e8f0', minor: '#475569',
    dateBox: '#0b1020', dateRim: 'none', date: '#fbbf24', hand: '#e2e8f0', second: '#f97316', pin: '#0b1020',
  },
  high: {
    page: '#ffffff', face: '#ffffff', rim: '#000000', tick: '#000000', minor: '#000000',
    dateBox: '#ffffff', dateRim: '#000000', date: '#000000', hand: '#000000', second: '#000000', pin: '#ffffff',
  },
  inks: {
    page: '#000000', face: '#000000', rim: '#0000ff', tick: '#ffffff', minor: '#ffffff',
    dateBox: '#000000', dateRim: '#ffff00', date: '#ffff00', hand: '#ffffff', second: '#ff0000', pin: '#000000',
  },
}

export function get(app, context) {
  const t = themeOf(app)
  // The dial is 480 units across and stays round: the view around it grows with the panel.
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const unit = 480 / Math.min(W, H)
  const viewW = W * unit, viewH = H * unit
  const viewX = C - viewW / 2, viewY = C - viewH / 2
  const now = app.config.at ? new Date(app.config.at) : new Date()
  const s = now.getSeconds()
  const m = now.getMinutes() + s / 60
  const h = (now.getHours() % 12) + m / 60
  const tau = Math.PI * 2
  // A round panel: the face is the whole glass, the dial grown to reach the rim.
  const round = context?.round === true
  return (
    <svg width={W} height={H} viewBox={`${viewX} ${viewY} ${viewW} ${viewH}`}>
      <rect x={viewX} y={viewY} width={viewW} height={viewH} fill={t.page} />
      {round ? <circle cx={C} cy={C} r={C} fill={t.face} /> : <circle cx={C} cy={C} r={220} fill={t.face} />}
      {round ? <circle cx={C} cy={C} r={C - 4} fill="none" stroke={t.rim} strokeWidth={6} /> : <circle cx={C} cy={C} r={220} fill="none" stroke={t.rim} strokeWidth={4} />}
      <g transform={round ? `translate(${C} ${C}) scale(${ROUND_SCALE}) translate(${-C} ${-C})` : undefined}>
      {Array.from({ length: 60 }).map((_, i) => (
        <Hand angle={(i * tau) / 60} from={i % 5 === 0 ? 178 : 194} to={204}
          width={i % 5 === 0 ? 6 : 2} color={i % 5 === 0 ? t.tick : t.minor} />
      ))}
      <rect x={C + 52} y={C - 18} width={88} height={36} rx={8} fill={t.dateBox} stroke={t.dateRim} strokeWidth={2} />
      <text x={C + 96} y={C + 9} fontSize={24} fill={t.date} textAnchor="middle">{`${days[now.getDay()]} ${now.getDate()}`}</text>
      <Hand angle={(h * tau) / 12} from={-16} to={110} width={12} color={t.hand} />
      <Hand angle={(m * tau) / 60} from={-20} to={170} width={8} color={t.hand} />
      <Hand angle={(s * tau) / 60} from={-30} to={186} width={3} color={t.second} />
      <circle cx={C} cy={C} r={9} fill={t.second} />
      <circle cx={C} cy={C} r={3} fill={t.pin} />
      </g>
    </svg>
  )
}
